const char *T(const char *es)
{
	if (!g_ui_en || !es)
		return es;
	for (unsigned i = 0; i < sizeof(tbl) / sizeof(tbl[0]); i++)
		if (tbl[i][0] == es || !strcmp(tbl[i][0], es))
			return tbl[i][1];
	return es;
}
